#include <stdio.h>
#include <stdlib.h>

int main(void) {
    void *huge = malloc((size_t)-1);        /* 不可能满足的请求 */
    printf("请求 (size_t)-1 字节 -> %s\n", huge ? "成功(意外)" : "返回 NULL");

    void *small = malloc(64);
    printf("请求 64 字节 -> %s\n", small ? "成功" : "失败");
    free(small);
    return 0;
}
